import {dateValid,labDefs} from './import.mjs';
export const clinicalRuntimeTranslations={};
const B=(en,tr)=>{clinicalRuntimeTranslations[tr]=en;return {en,tr};};
const num=(v,min,max)=>typeof v==='number'&&Number.isFinite(v)&&v>=min&&v<=max;
const yesno=v=>['yes','no'].includes(v);
// Match the core engine's error-metadata contract: absent is allowed, but
// malformed lists/entries (including sparse holes) cannot authorize a result.
// Valid unrelated field flags do not invalidate independent lab arithmetic.
const flagsAllow=(flags,keys)=>{
 if(flags===undefined)return true;
 if(!Array.isArray(flags))return false;
 const entries=Array.from(flags);
 return entries.every(key=>typeof key==='string'&&key.trim().length>0)&&entries.every(key=>!keys.includes(key.trim()));
};
const paired=(d,m)=>flagsAllow(d.inputErrors,['labsConfirmed','labDate','visitDate'])&&flagsAllow(m.invalidFields,['markerConfirmed','markerDate'])&&d.labsConfirmed===true&&m.markerConfirmed===true&&dateValid(d.labDate)&&dateValid(d.visitDate)&&m.markerDate===d.labDate&&d.labDate<=d.visitDate;
export const conditionOptions=[
 ['none',B('No known chronic disease','Bilinen kronik hastalık yok')],['ibd',B('Inflammatory bowel disease','İnflamatuar bağırsak hastalığı')],['shortBowel',B('Short bowel / intestinal failure','Kısa bağırsak / bağırsak yetmezliği')],['kidney',B('Chronic kidney disease','Kronik böbrek hastalığı')],['liver',B('Chronic liver disease','Kronik karaciğer hastalığı')],['heart',B('Heart failure','Kalp yetmezliği')],['diabetes',B('Diabetes','Diyabet')],['copd',B('Chronic respiratory disease','Kronik solunum hastalığı')],['cancer',B('Active cancer','Aktif kanser')],['parkinson',B('Parkinson disease','Parkinson hastalığı')],['stroke',B('Stroke / neurological disability','İnme / nörolojik engel')],['other',B('Other chronic condition','Diğer kronik hastalık')],
];
export function enforceClinicalContext(core,context){
 const nitrogenMessages=context.nitrogenBlockers||[];
 if(!context.blockers.length&&!nitrogenMessages.length)return core;
 const messages=context.blockers.map(v=>v.tr);
 const suppressed=nitrogenMessages.length&&core.indices?.nitrogen;
 const explanation=B('Nitrogen balance was withheld: renal history or major intestinal losses conflict with the simple estimate. Reconcile these conditions with the clinical team; a normal blood creatinine does not resolve the conflict.','Azot dengesi yorumlanmadı: böbrek öyküsü veya önemli bağırsak kaybı basit tahminle uyumsuz. Bu koşulları klinik ekiple uzlaştırın; normal kan kreatinini çelişkiyi gidermez.');
 return {...core,plan:context.blockers.length?null:core.plan,blockers:[...new Set([...core.blockers,...messages])],...(suppressed?{indices:{...core.indices,nitrogen:null},metabolic:{title:'Katabolik/anabolik durum belirlenemedi',detail:explanation.tr}}:{}),trace:[...core.trace.filter(v=>!suppressed||!(/^(Tahmini azot dengesi =|Toplama:)/.test(v))),...messages,...(suppressed?[explanation.tr,...nitrogenMessages.map(v=>v.tr)]:[])]};
}
export function evaluateContext(d={},m={},functionResults=[]){
 const conditions=Array.isArray(m.conditions)?m.conditions:[],known=new Set(conditionOptions.map(([id])=>id));
 const validConditions=conditions.length>0&&conditions.every(id=>known.has(id))&&!(conditions.includes('none')&&conditions.length>1);
 const notes=[],blockers=[];
 const add=(en,tr)=>blockers.push(B(en,tr));
 if(!validConditions||m.contextReviewed!==true)add('Record and clinically review the chronic-disease history.','Kronik hastalık öyküsünü kaydedin ve klinik olarak değerlendirin.');
 if(conditions.includes('ibd')){
   notes.push(B('IBD: distinguish Crohn’s/UC and active disease/remission. Review absorption, losses, intake and micronutrients; the same product/target does not fit all phases.','İBH: Crohn/ülseratif koliti ve aktif hastalık/remisyonu ayırın. Emilim, kayıp, alım ve mikrobesinleri değerlendirin; aynı ürün/hedef her faza uymaz.'));
   if(!['crohn','uc','other'].includes(m.ibdType)||!['active','remission'].includes(m.ibdPhase))add('Specify IBD type and phase before a general formula draft.','Genel mama taslağından önce İBH türünü ve fazını belirtin.');
 }
 if(conditions.includes('kidney')&&d.renal==='none')add('Kidney history conflicts with the renal field; reconcile AKI/CKD/KRT.','Böbrek öyküsü böbrek alanıyla çelişiyor; AKI/CKD/KRT durumunu düzeltin.');
 if(conditions.includes('shortBowel')||m.highOutputStoma===true)add('Intestinal failure/high-output losses require a specialist fluid, electrolyte and nutrition plan; the general automatic draft is disabled.','Bağırsak yetmezliği/yüksek debili kayıp uzman sıvı, elektrolit ve beslenme planı gerektirir; genel otomatik taslak kapalıdır.');
 if(m.bowelObstruction===true)add('Possible obstruction: reassess gastrointestinal suitability and feeding route; no general oral/enteral draft.','Olası obstrüksiyon: gastrointestinal uygunluğu ve yolu yeniden değerlendirin; genel oral/enteral taslak oluşturulmaz.');
 if(conditions.includes('diabetes'))notes.push(B('Review glucose, carbohydrate exposure from all sources and diabetes treatment. This version does not calculate insulin or rank formulas by brand.','Glukozu, tüm kaynaklardan karbonhidratı ve diyabet tedavisini değerlendirin. Bu sürüm insülin hesaplamaz veya mamaları markaya göre sıralamaz.'));
 if(conditions.includes('heart')||conditions.includes('liver'))notes.push(B('Review fluid status, sodium/electrolytes, organ function and dosing weight with the responsible clinician.','Sıvı durumunu, sodyum/elektrolitleri, organ işlevini ve doz ağırlığını sorumlu klinisyenle değerlendirin.'));
 if(conditions.includes('parkinson'))notes.push(B('Review levodopa–meal timing with neurology/pharmacy while preserving adequate total intake.','Yeterli toplam alımı koruyarak levodopa–öğün zamanlamasını nöroloji/eczacılıkla değerlendirin.'));
 if(conditions.includes('stroke')||conditions.includes('parkinson'))notes.push(B('Neurological weakness, alertness and dysphagia can confound grip/performance and affect the safe feeding route.','Nörolojik güçsüzlük, uyanıklık ve disfaji kavrama/performansı etkileyebilir ve güvenli beslenme yolunu değiştirebilir.'));
 const safety=functionResults.find(r=>r.id==='swallow-safety')?.values;
 if(d.route==='oral'&&safety?.hasUnsafeSwallow===true)add('Swallowing/alertness red flags: oral formula calculation is blocked pending clinical swallowing assessment.','Yutma/uyanıklık alarm bulguları: klinik yutma değerlendirmesine kadar oral mama hesabı engellendi.');
 if(d.route==='oral'&&safety?.oralRecordConflict===true)add('FOIS 1 (nothing by mouth) conflicts with an oral formula route; reconcile the records.','FOIS 1 (ağızdan alım yok), oral mama yoluyla çelişiyor; kayıtları düzeltin.');
 const nitrogenBlockers=[];
 if(conditions.includes('kidney'))nitrogenBlockers.push(B('Kidney history must be reconciled before interpreting this simplified nitrogen balance.','Bu basit azot dengesi yorumlanmadan önce böbrek öyküsü uzlaştırılmalıdır.'));
 if(conditions.includes('shortBowel')||m.highOutputStoma===true)nitrogenBlockers.push(B('Intestinal failure or major intestinal losses make the fixed-loss nitrogen estimate unsuitable.','Bağırsak yetmezliği veya önemli bağırsak kayıpları sabit kayıp varsayımlı azot tahminini uygunsuz kılar.'));
 return {notes,blockers,nitrogenBlockers,conditions,reviewed:validConditions&&m.contextReviewed===true};
}

export function evaluateMarkers(d={},m={}){
 let urea=null,ucr=null,bunRatio=null;
 if(paired(d,m)&&flagsAllow(d.inputErrors,['creatinine'])&&flagsAllow(m.invalidFields,['ureaValue','ureaAnalyte','ureaUnit'])&&num(d.creatinine,labDefs.creatinine.min,labDefs.creatinine.max)&&num(m.ureaValue,0,1000)){
  if(m.ureaAnalyte==='urea'&&m.ureaUnit==='mg/dL')urea=m.ureaValue;
  if(m.ureaAnalyte==='urea'&&m.ureaUnit==='mmol/L')urea=m.ureaValue*6.006;
  if(m.ureaAnalyte==='bun'&&m.ureaUnit==='mg/dL')urea=m.ureaValue*2.144;
  if(urea!==null){ucr=urea/d.creatinine;bunRatio=urea/2.144/d.creatinine;}
 }
 const crpRatio=paired(d,m)&&flagsAllow(d.inputErrors,['crp'])&&flagsAllow(m.invalidFields,['crpULN'])&&num(d.crp,0,1000)&&num(m.crpULN,0.01,1000)?d.crp/m.crpULN:null;
 const dateOk=dateValid(m.sofaDate)&&dateValid(d.visitDate)&&m.sofaDate<=d.visitDate;
 const ok=d.context==='icu'&&num(d.age,18,120)&&m.sofaConfirmed===true&&dateOk;
 const components={brain:null,respiratory:null,cardiovascular:null,liver:null,kidney:null,hemostasis:null};
 if(ok){
   if(num(m.sofaGcs,3,15)&&Number.isInteger(m.sofaGcs)&&yesno(m.sofaDelirium))components.brain=Math.max(m.sofaGcs>=15?0:m.sofaGcs>=13?1:m.sofaGcs>=9?2:m.sofaGcs>=6?3:4,m.sofaDelirium==='yes'?1:0);
   if(m.sofaVentilation==='ecmo')components.respiratory=4;
   else if(num(m.sofaPaO2,1,800)&&num(m.sofaFiO2,0.21,1)&&['none','advanced'].includes(m.sofaVentilation)){
     const pf=m.sofaPaO2/m.sofaFiO2;
     components.respiratory=pf>300?0:pf>225?1:pf>150?2:m.sofaVentilation==='advanced'?(pf>75?3:4):2;
   }
   if(m.sofaMechanical==='yes')components.cardiovascular=4;
   else if(m.sofaMechanical==='no'&&num(m.sofaNe,0,10)&&num(m.sofaEpi,0,10)&&yesno(m.sofaOtherVaso)){
     const dose=m.sofaNe+m.sofaEpi,other=m.sofaOtherVaso==='yes';
     components.cardiovascular=dose>0.4?4:dose>0.2?(other?4:3):dose>0?(other?3:2):other?2:num(m.sofaMap,1,200)?(m.sofaMap>=70?0:1):null;
   }
   if(num(m.sofaBilirubin,0,60))components.liver=m.sofaBilirubin<=1.2?0:m.sofaBilirubin<=3?1:m.sofaBilirubin<=6?2:m.sofaBilirubin<=12?3:4;
   if(m.sofaRrt==='yes')components.kidney=4;
   else if(m.sofaRrt==='no'&&num(m.sofaCreatinine,0.01,30)&&['normal','oliguria6','oliguria12','oliguria24','anuria12'].includes(m.sofaUrine))components.kidney=Math.max(m.sofaCreatinine<=1.2?0:m.sofaCreatinine<=2?1:m.sofaCreatinine<=3.5?2:3,{normal:0,oliguria6:1,oliguria12:2,oliguria24:3,anuria12:3}[m.sofaUrine]);
   if(num(m.sofaPlatelets,0,2000))components.hemostasis=m.sofaPlatelets>150?0:m.sofaPlatelets>100?1:m.sofaPlatelets>80?2:m.sofaPlatelets>50?3:4;
 }
 const score=Object.values(components).every(v=>v!==null)?Object.values(components).reduce((a,b)=>a+b,0):null;
 const saps=num(m.saps2Total,0,163)&&Number.isInteger(m.saps2Total)&&m.sapsConfirmed===true&&dateValid(m.sapsDate)&&dateValid(d.visitDate)&&m.sapsDate<=d.visitDate&&d.context==='icu'&&num(d.age,18,120)?m.saps2Total:null;
 return [
  {id:'ucr',title:B('Urea/creatinine · research proxy','Üre/kreatinin · araştırma belirteci'),status:ucr===null?'incomplete':'review',summary:ucr===null?B('Need same-date verified creatinine and explicit urea/BUN analyte and units.','Aynı tarihli doğrulanmış kreatinin, açık üre/BUN analiti ve birim gerekir.'):B(`Urea/creatinine (both mg/dL): ${ucr.toFixed(2)}. BUN/creatinine: ${bunRatio.toFixed(2)}. These are different ratios.`,`Üre/kreatinin (ikisi mg/dL): ${ucr.toFixed(2)}. BUN/kreatinin: ${bunRatio.toFixed(2)}. Bunlar farklı oranlardır.`),details:[B('Renal/liver function, hydration, GI bleeding, RRT and exogenous protein alter this ratio. There is no validated universal anabolic/catabolic or feeding-dose cutoff.','Böbrek/karaciğer işlevi, hidrasyon, GI kanama, KRT ve dış protein bu oranı değiştirir. Doğrulanmış evrensel anabolik/katabolik veya besleme dozu eşiği yoktur.'),B('The September 2026 ICU analysis found associations dependent on sampling day and baseline AKI. The ward EFFORT analysis did not detect different nutrition-treatment responses by UCR. Neither establishes a UCR-selected dose; study units and populations differ from this display.','Eylül 2026 YBÜ analizinde ilişki ölçüm günü ve başlangıç AKI durumuna bağlıydı. Servis EFFORT analizinde UCR’ye göre farklı beslenme tedavisi yanıtı saptanmadı. İkisi de UCR’ye göre doz seçtirmez; çalışma birimleri ve hasta grupları bu gösterimden farklıdır.')],values:{ureaMgDl:urea,ucr,bunCreatinineRatio:bunRatio},sourceIds:['ucr-crrt-2025','ucr-aki-mortality-posthoc-2026','ucr-effort-ward-2025']},
  {id:'crp',title:B('Inflammatory marker context','İnflamatuar belirteç bağlamı'),status:crpRatio===null?'incomplete':'review',summary:crpRatio===null?B('Enter the local CRP upper reference and confirm matching laboratory dates.','Yerel CRP üst referansını girin ve eşleşen laboratuvar tarihlerini doğrulayın.'):B(`CRP is ${crpRatio.toFixed(2)} × the entered local upper reference.`,`CRP, girilen yerel üst referansın ${crpRatio.toFixed(2)} katıdır.`),details:[B('This arithmetic ratio does not grade systemic inflammation or determine a protein target. Interpret the cause, clinical course and organ function.','Bu aritmetik oran sistemik inflamasyonu derecelendirmez veya protein hedefini belirlemez. Nedeni, klinik seyri ve organ işlevini değerlendirin.')],values:{crpRatio},sourceIds:['aspen-visceral-2021']},
  {id:'sofa2',title:B('SOFA-2 · 2025','SOFA-2 · 2025'),status:score===null?'incomplete':'review',summary:score===null?B('Complete and verify the adult ICU measurements for all six organ systems. Missing values are not zero.','Altı organ sisteminin erişkin YBÜ ölçümlerini tamamlayıp doğrulayın. Eksik değer sıfır değildir.'):B(`SOFA-2 = ${score}/24. Describes organ dysfunction; not inflammation severity or a nutrition dose.`,`SOFA-2 = ${score}/24. Organ işlev bozukluğunu tanımlar; inflamasyon şiddeti veya beslenme dozu değildir.`),details:[B('Use a defined 24-hour window and the original footnotes; assess GCS free of sedation confounding. This implementation uses PaO₂/FiO₂, not the optional SpO₂ proxy. Resource/treatment-ceiling exceptions require manual specialist scoring.','Tanımlı 24 saatlik pencere ve özgün dipnotları kullanın; GKS’yi sedasyon etkisinden ayırın. Bu uygulama PaO₂/FiO₂ kullanır; opsiyonel SpO₂ vekilini kullanmaz. Kaynak/tedavi sınırı istisnaları elle uzman puanlaması gerektirir.')],values:{score,components},sourceIds:['sofa2-2025']},
  {id:'saps2',title:B('SAPS II · recorded total','SAPS II · kaydedilmiş toplam'),status:saps===null?'incomplete':'review',summary:saps===null?B('Enter a clinician-calculated, verified SAPS II total from the original 17-variable form.','Özgün 17 değişkenli formdan klinisyenin hesapladığı doğrulanmış SAPS II toplamını girin.'):B(`Recorded SAPS II: ${saps}/163. This panel does not recalculate its 17 components or estimate mortality.`,`Kaydedilmiş SAPS II: ${saps}/163. Bu panel 17 alt değişkeni yeniden hesaplamaz veya mortalite tahmin etmez.`),details:[B('SAPS II is an illness-severity model. It is not an inflammation scale or a validated calorie/protein titration rule.','SAPS II hastalık şiddeti modelidir. İnflamasyon ölçeği veya doğrulanmış kalori/protein titrasyon kuralı değildir.')],values:{score:saps},sourceIds:['saps2-1993']},
 ];
}

export const clinicalEnglishTranslations={};
const R=r=>Object.fromEntries(Object.entries(r).map(([key,value])=>{if(value&&typeof value==='object'&&'en'in value){clinicalEnglishTranslations[value.tr]=value.en;return[key,value.tr];}return[key,value];}));
export const clinicalSources=[
 R({id:'sofa2-2025',title:'Development and Validation of the Sequential Organ Failure Assessment (SOFA)-2 Score',year:2025,kind:B('Multicenter model development/validation','Çok merkezli model geliştirme/validasyon'),url:'https://jamanetwork.com/journals/jama/fullarticle/2840822',doi:'10.1001/jama.2025.20516',access:B('Original publisher text and scoring table','Özgün yayıncı metni ve puanlama tablosu'),summary:B('Six organ systems, 0–24; adult ICU validation in international cohorts.','Altı organ sistemi, 0–24; uluslararası erişkin YBÜ kohortlarında validasyon.'),application:B('Calculates organ components with explicit units and no missing-value imputation.','Açık birimlerle ve eksik değere atama yapmadan organ alt puanlarını hesaplar.'),limitations:B('Not an inflammation scale, sepsis diagnosis or nutrition-dose trial; no individual mortality probability is calculated.','İnflamasyon ölçeği, sepsis tanısı veya beslenme dozu deneyi değildir; bireysel mortalite olasılığı hesaplanmaz.')}),
 R({id:'saps2-1993',title:'A New Simplified Acute Physiology Score (SAPS II)',year:1993,kind:B('Original severity model','Özgün şiddet modeli'),url:'https://jamanetwork.com/journals/jama/article-abstract/409979',doi:'10.1001/jama.1993.03510240069035',access:B('Original abstract','Özgün özet'),summary:B('Seventeen variables developed from 13,152 adult ICU admissions.','13.152 erişkin YBÜ yatışından geliştirilen 17 değişken.'),application:B('Clinician-calculated total is recorded separately from nutrition targets.','Klinisyenin hesapladığı toplam, beslenme hedeflerinden ayrı kaydedilir.'),limitations:B('Historical population and calibration; not a validated nutritional titration rule.','Tarihsel popülasyon ve kalibrasyon; doğrulanmış beslenme titrasyon kuralı değildir.')}),
 R({id:'espen-ibd-2023',title:'ESPEN guideline on Clinical Nutrition in inflammatory bowel disease',year:2023,kind:B('Official guideline','Resmî kılavuz'),url:'https://2022.espen.org/files/ESPEN-Guidelines/ESPEN_guideline_on_Clinical_nutrition_in_inflammatory_bowel_disease.pdf',doi:'10.1016/j.clnu.2022.12.004',access:B('Official full text','Resmî tam metin'),summary:B('Separates Crohn’s/UC, active disease/remission, nutrition risk and complications.','Crohn/ülseratif kolit, aktif hastalık/remisyon, beslenme riski ve komplikasyonları ayırır.'),application:B('Disease context informs clinical review; no brand or automatic SCFA prescription.','Hastalık bağlamı klinik değerlendirmeye katılır; marka veya otomatik SCFA reçetesi verilmez.'),limitations:B('An IBD guideline does not establish an ICU-wide supplement or optimal individual dose.','İBH kılavuzu bütün YBÜ için takviye veya bireysel optimum doz belirlemez.')}),
 R({id:'butyrate-ibd-print-2026',title:'Impact of oral butyrate on clinical and biochemical parameters in IBD: A randomized placebo-controlled study targeting gut microbiota',year:2026,kind:B('Original randomized trial','Özgün randomize çalışma'),url:'https://pubmed.ncbi.nlm.nih.gov/41354580/',doi:'10.1016/j.dld.2025.11.014',sampleSize:140,onlineDate:'2025-12-06',printDate:'2026-01',access:B('Original indexed abstract; full methods not reviewed','Özgün indekslenen özet; tam yöntem incelenmedi'),summary:B('60 Crohn’s and 80 UC patients received microencapsulated butyrate or placebo alongside conventional therapy; clinical/biochemical and quality-of-life signals were reported.','60 Crohn ve 80 ülseratif kolit hastasında standart tedavi yanında mikroenkapsüle bütirat/plasebo; klinik/biyokimyasal ve yaşam kalitesi sinyalleri bildirildi.'),application:B('Indication-specific gastroenterology review may be considered; no automatic supplementation.','Endikasyona özgü gastroenteroloji değerlendirmesi düşünülebilir; otomatik takviye yapılmaz.'),limitations:B('Abstract supplies no primary between-group CI. Online 2025/issue 2026; microbiome subgroup findings are not a validated selection biomarker.','Özet primer gruplar arası GA sağlamıyor. Çevrimiçi 2025/sayı 2026; mikrobiyom alt grupları doğrulanmış seçim belirteci değildir.')}),
 R({id:'scfa-mixture-uc-1997',title:'Short chain fatty acid rectal irrigation for left-sided ulcerative colitis: a randomised placebo controlled trial',year:1997,kind:B('Original randomized trial','Özgün randomize çalışma'),url:'https://pubmed.ncbi.nlm.nih.gov/9176076/',doi:'10.1136/gut.40.4.485',sampleSize:103,access:B('Original abstract','Özgün özet'),summary:B('Rectal SCFA mixture trial: 91 completed; overall improvement 33% vs 20%, p=.14.','Rektal SCFA karışımı deneyi: 91 tamamlayan; genel iyileşme %33 ve %20, p=0,14.'),application:B('Acetate/propionate/butyrate mixtures are not equivalent to isolated oral supplements.','Asetat/propiyonat/bütirat karışımları izole oral takviyelerle eşdeğer değildir.'),limitations:B('No significant overall efficacy; subgroup/open-label findings do not establish routine use or a dose rule.','Genel etkililik anlamlı değil; alt grup/açık etiket bulguları rutin kullanım veya doz kuralı oluşturmaz.')}),
 R({id:'ucr-crrt-2025',title:'The Urea-Creatinine Ratio as Marker of Catabolism Is Affected by Continuous Renal Replacement Therapy',year:2025,kind:B('Original observational research','Özgün gözlemsel araştırma'),url:'https://pubmed.ncbi.nlm.nih.gov/40506980/',doi:'10.3390/diagnostics15111408',access:B('Original open full text; methods/results/discussion reviewed','Özgün açık tam metin; yöntem/sonuç/tartışma incelendi'),summary:B('CRRT changes UCR and complicates interpreting it as a catabolism proxy.','CRRT UCR’yi değiştirir ve katabolizma vekili olarak yorumunu güçleştirir.'),application:B('Explicitly distinguish analytes/units and show renal/RRT confounding.','Analit/birimleri açıkça ayırır; böbrek/KRT etkisini görünür tutar.'),limitations:B('Not a validated UCR-guided treatment trial or universal threshold.','Doğrulanmış UCR rehberli tedavi deneyi veya evrensel eşik değildir.')}),
];
